using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ResetRunesApplyEffectAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/ResetRunesApplyEffect Action")]
public class ResetRunesApplyEffectAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private BattleAction effectAction;

	[SerializeField]
	private OmenLogic targetToApplyLogic;

	[SerializeField]
	private RefreshAction refreshAction;

	public BattleAction EffectAction => effectAction;

	public RefreshAction RefreshAction => refreshAction;

	public override void CastAmount(int amount, GameObject source)
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.TryEnterNoInteractionState();
		targetToApplyLogic.ActivateOmen(effectAction, amount, null, source);
		refreshAction.OnResetUsedRunesPublic.Raise();
		instance.TryEnterChooseActionState();
	}
}
